	dataDir := t.TempDir()
	p := startServer(t, dataDir)
	labeled := `{"events":[
		{"id":"e1","service":"gateway","severity":"critical","message":"spike","at":"2026-10-01T09:00:00Z","labels":{"env":"prod","version":"v2"}},
