	]}`
	if counts := postEvents(t, p, labeled); counts["created"] != 2 {
		t.Fatalf("created=%v", counts)
	}

	p.signal(t, syscall.SIGKILL)
	p.waitExit(t, -1)
	waitTCPPortClosed(t, p.addr)

	p2 := startServer(t, dataDir)
	got := getEvents(t, p2, "")
	if len(got) != 2 {
		t.Fatalf("recovery after SIGKILL: %+v", got)
	}
