	filtered := getEvents(t, p2, "?label=env=prod")
	if len(filtered) != 1 || filtered[0]["id"] != "e1" {
		t.Fatalf("label filter after restart: %+v", filtered)
	}

	p2.signal(t, syscall.SIGTERM)
	p2.waitExit(t, 0)
}

